@Bean
public KStream<String, OrderEvent> orderStream(StreamsBuilder builder) {
    KStream<String, OrderEvent> orders = builder.stream("orders");

    // Агрегация: сумма заказов по клиенту -> KTable + State Store
    KTable<String, Double> totalByCustomer = orders
        .groupBy((key, order) -> order.customerId(),
                 Grouped.with(Serdes.String(), orderSerde))
        .aggregate(
            () -> 0.0,
            (customerId, order, total) -> total + order.amount(),
            Materialized.<String, Double, KeyValueStore<Bytes, byte[]>>as("totals-store")
                .withValueSerde(Serdes.Double()));

    totalByCustomer.toStream().to("customer-totals");
    return orders;
}
