@Component
@RequiredArgsConstructor
public class BackpressureConsumer {
    private final KafkaListenerEndpointRegistry registry;

    @KafkaListener(id = "orders", topics = "orders")
    public void handle(OrderEvent event) {
        if (downstreamOverloaded()) {
            registry.getListenerContainer("orders").pause();
        }
        processOrder(event);
    }

    @Scheduled(fixedDelay = 5000)
    public void resumeIfHealthy() {
        var container = registry.getListenerContainer("orders");
        if (container.isContainerPaused() && downstreamHealthy()) {
            container.resume();
        }
    }
}
